// ==UserScript==
// @name         Legend of Aethra - Soundtrack
// @namespace    eaglewing.legend-of-aethra
// @version      1.0.0
// @description  Optional music for Legend of Aethra, every track: intro, adventure, fight, fight2, village, calm village, manor, road, lost village, peaceful, dungeon, cave, tension, temple, dark forest, clearing, boat, aquatic, sunny, story, sad, mystical, revelation, lament, melancholia, chill, quiet, dream, final area, dark castle, ruins, crypt, curse, ascension, good time, end theme, credit. Hands the tracks to the game when it starts; makes no requests and stores nothing.
// @author       Eaglewing [571041]
// @match        https://www.torn.com/*
// @updateURL    https://github.com/Eaglewing91/Legend-of-Aethra/raw/main/build/Legend-of-Aethra-Soundtrack.user.js
// @downloadURL  https://github.com/Eaglewing91/Legend-of-Aethra/raw/main/build/Legend-of-Aethra-Soundtrack.user.js
// @grant        none
// @run-at       document-idle
// @noframes
// ==/UserScript==
/* Music from "Ninja Adventure" by Pixel-boy and AAA (CC0). Packaging (c) Eaglewing [571041], all rights reserved; for use on
   Torn only. This script makes no requests and needs no API key. It only answers the game's 'aethra-music:request' page
   event with one 'aethra-music' event carrying its tracks.
   TERMS OF SERVICE
   | Data Storage          | No                       |
   | Data Sharing          | Nobody                   |
   | Purpose of Use        | Public amusement         |
   | Key Storage & Sharing | Not stored / Not shared  |
   | Key Access Level      | None (no API key needed) |
*/
(function () {
  const T = {"intro": "", "adventure": "", "fight": "", "fight2": "", "village": "", "calm_village": "", "manor": "", "road": "", "lost_village": "", "peaceful": "", "dungeon": "", "cave": "", "tension": "", "temple": "", "dark_forest": "", "clearing": "", "boat": "", "aquatic": "", "sunny": "", "story": "", "sad": "", "mystical": "", "revelation": "", "lament": "", "melancholia": "", "chill": "", "quiet": "", "dream": "", "final_area": "", "dark_castle": "", "ruins": "", "crypt": "", "curse": "", "ascension": "", "good_time": "", "end_theme": "", "credit": ""};
  const send = function () { document.dispatchEvent(new CustomEvent('aethra-music', { detail: JSON.stringify({ part: 1, tracks: T }) })); };
  document.addEventListener('aethra-music:request', send);
  document.documentElement.dataset['aethraMusic1'] = '1.0.0';
})();
